#include <stdio.h>

int main() {
    int K, N;
    scanf("%d %d", &K, &N);

    char alphabet[100];
    char message[1005];

    scanf("%s", alphabet);
    scanf("%s", message);

    int present[256] = {0};

    for (int i = 0; i < K; i++) {
        present[(unsigned char)alphabet[i]] = 1;
    }

    int ok = 1;
    for (int i = 0; i < N; i++) {
        if (!present[(unsigned char)message[i]]) {
            ok = 0;
            break;
        }
    }

    printf("%c\n", ok ? 'S' : 'N');

    return 0;
}
